sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //Mss 
        var taskNum = '';
        var tradeTask = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
        tradeTask.addQuery("number", current.object_id);
        tradeTask.query();
        if (tradeTask.next()) {

            var child = new GlideRecord("x_hsb11_mss_smh_child_aggregated_trade_chat_queue");
            child.addQuery('trade_case_task', tradeTask.sys_id);
            child.query();
            if (child.next()) {
                if (child.parent.trade_count == 1) {
                    var OutboundtaskNew = new GlideRecord("x_hsb11_mss_sw_hsbc_outbound_symphony_message_log");
                    OutboundtaskNew.initialize();
                    OutboundtaskNew.servicenow_task_id = current.object_id;
                    OutboundtaskNew.type = "Recall";
                    OutboundtaskNew.setValue("active", true);
                    OutboundtaskNew.message_body = child.parent.encryptedmessageid;
                    OutboundtaskNew.state = "Ready to be sent";
                    OutboundtaskNew.source = 'Equities';
                    OutboundtaskNew.insert();

                }
            }
        }
    } catch (e) {
        gs.error('[BR][HSBC - Recall response from client]: ' + e.getMessage());
    }

})(current, previous);
